mapper.select:
select hidden_obj_id as deviceId, count(id) as num, COALESCE(SUM(if(`state` = 'FINISHED',1,0)),0) as `handler_num`, COALESCE(SUM(if(`state` != 'FINISHED',1,0)),0) as `un_handler_num` from hidden_danger_new
hidden_obj_type = 'DEVICE'
and hidden_obj_id in
#{id}
and create_time between #{param.period.begin} and #{param.period.end}
group by hidden_obj_id

SELECT COUNT(id) from hidden_danger_new
WHERE
      hidden_obj_id = #{deviceId}
    and submit_time BETWEEN #{begin} and #{end}

select a.submit_time as submitTime,a.name,a.hidden_obj_name as hiddenDangerObj,t.type_name as source,d.name as classify,
e.name as levelName, a.submit_staff as submitter,a.state,a.result
from hidden_danger_new a
left join hidden_danger_type d on a.hidden_type_id = d.id
left join hidden_danger_level e on a.urgency_level = e.id
left join inspect_record_to_business b on a.process_ins_id = b.business_id and b.business_category = 'HIDDENDANGER'
left JOIN inspect_record c on b.record_id = c.id
LEFT JOIN inspect_task t on t.id = c.task_id


        and c.task_id = #{param.taskId}


        and c.organization_id = #{param.depId}


        and c.user_id = #{param.staffId}


        and c.target_id = #{param.objId}


        and a.create_time between #{param.period.begin} and #{param.period.end}


        and a.state = 'WAITING_FOR_HANDLE'


        and a.state = 'FINISHED'


        and a.state = 'WAITING_FOR_HANDLE'

select count(DISTINCT a.id) from hidden_danger_new a
left join inspect_record_to_business b on a.process_ins_id = b.business_id and b.business_category = 'HIDDENDANGER'
left join inspect_record c on b.record_id = c.id


        and c.task_id = #{param.taskId}


        and c.organization_id = #{param.depId}


        and c.user_id = #{param.staffId}


        and c.target_id = #{param.objId}


        and a.submit_time between #{param.period.begin} and #{param.period.end}


        and a.state = 'WAITING_FOR_HANDLE'


        and a.state = 'FINISHED'


        and a.state = 'WAITING_FOR_HANDLE'

select c.organization_id as depId, count(DISTINCT a.id) as abnormalHiddenDangerNum, count(DISTINCT case when a.state = 'FINISHED' then a.id end) as haveDoneHiddenDangerNum from hidden_danger_new a left join inspect_record_to_business b on a.process_ins_id = b.business_id and b.business_category = 'HIDDENDANGER' left join inspect_record c on b.record_id = c.id
and c.organization_id in
#{depId}
and a.submit_time between #{period.begin} and #{period.end}
group by c.organization_id

select c.user_id as staffId, count(DISTINCT a.id) as abnormalHiddenDangerNum, count(DISTINCT case when a.state = 'FINISHED' then a.id end) as haveDoneHiddenDangerNum from hidden_danger_new a left join inspect_record_to_business b on a.process_ins_id = b.business_id and b.business_category = 'HIDDENDANGER' left join inspect_record c on b.record_id = c.id
and c.user_id in
#{staffId}
and a.submit_time between #{period.begin} and #{period.end}
group by c.user_id
